# region: emit
def emit(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.lstrip('-').isdigit():
            out.append(int(s))
            return out
    return out

# region: digest
def digest(xs, limit=12):
    return [v if v <= limit else limit for v in xs]

# region: gather
def gather(xs, factor=2):
    return [v * factor for v in xs]

# region: shape
def shape(xs):
    return {'n': len(xs), 'min': min(xs) if xs else 0, 'span': (max(xs) - min(xs)) if xs else 0}

# region: fold
def fold(summary, name='beta'):
    out = dict(summary)
    out['label'] = name.upper() if summary.get('n', 0) else 'EMPTY'
    return out

# region: run
def run(raw):
    return fold(shape(gather(digest(emit(raw)))))

